import path from 'node:path';
import { createRequestHandler } from '@remix-run/server-runtime';
// Generated by the preceding Remix desktop build.
// @ts-ignore generated bundle has no TypeScript declaration
import * as build from '../build/server/index.js';
import { startLocalServer } from './local-server';

export { startLocalServer } from './local-server';
export { createLocalToolFactory } from './local-tools';
export { createCCompiler } from './c-runner';
export { createCAPI } from './c-api';

export async function startBackend(options: {
  token: string;
  assetsDir: string;
  workspace: string;
  auditFile: string;
  env: Record<string, string>;
  port?: number;
}) {
  return startLocalServer({ ...options, handler: createRequestHandler(build as any, 'production') });
}

if (process.env.BOLT_DESKTOP_UTILITY === '1') {
  const allowed = [
    'ANTHROPIC_API_KEY',
    'ANTHROPIC_MODEL',
    'LLM_PROVIDER',
    'LLM_BASE_URL',
    'LLM_MODEL',
    'LLM_API_KEY',
    'BOLT_C_ONLY',
    'BOLT_C_IMAGE',
    'BOLT_C_DOCKER_PATH',
    'BOLT_C_DOCKER_HOST',
  ];
  const env = Object.fromEntries(allowed.filter((key) => process.env[key]).map((key) => [key, process.env[key]!]));
  startBackend({
    token: process.env.BOLT_LOCAL_TOKEN || '',
    assetsDir: process.env.BOLT_ASSETS_DIR || path.join(__dirname, 'client'),
    workspace: process.env.BOLT_WORKSPACE || '',
    auditFile: process.env.BOLT_AUDIT_FILE || '',
    env,
    port: Number(process.env.BOLT_LOCAL_PORT) || 0,
  })
    .then((backend) => {
      (process as any).parentPort.postMessage({ type: 'ready', origin: backend.origin });
      (process as any).parentPort.on('message', (event: { data: { type: string } }) => {
        if (event.data?.type === 'shutdown') void backend.close().then(() => process.exit(0));
      });
      process.once('SIGTERM', () => {
        void backend.close().then(() => process.exit(0));
      });
    })
    .catch(() => {
      (process as any).parentPort.postMessage({
        type: 'failed',
        message: 'The local backend failed to start. Check the runtime build and local port.',
      });
      process.exit(1);
    });
}
